/bin/bash -lc "python3 - <<'PY'
import pandas as pd
from gprofiler import GProfiler
# quick rerun reads? no saved results. Let's just test a few IDs from previous output and one foreground manually.
gp=GProfiler(return_dataframe=True)
ids=['ENSG00000140465','ENSG00000063438','ENSG00000138061','ENSG00000184254','ENSG00000186352']
print(gp.convert(organism='hsapiens', query=ids, target_namespace='ENTREZGENE_ACC').head().to_string(index=False))
for bg in [None, 'custom']:
    kwargs={}
    if bg=='custom': kwargs['background']=ids+['ENSG00000227232']
    try:
        r=gp.profile(organism='hsapiens', query=ids, sources=['GO:BP'], user_threshold=1.0, **kwargs)
        print('bg',bg,'rows',0 if r is None else len(r))
        if r is not None and len(r): print(r[['native','name','p_value','intersection_size']].head().to_string(index=False))
    except Exception as e: print('ERR', bg, repr(e))
PY"

